"""Nexus IT Pack: UI/UX Designer Agent."""
from __future__ import annotations

from pydantic import BaseModel, Field
from nexus.providers.base import BaseModelProvider
from nexus.teams.it_pack.ba import ProductProposal
from nexus.teams.it_pack.solution_architect import SolutionBlueprint


class UiSpecification(BaseModel):
    """UI specification and working React component code generated by the Designer."""
    component_name: str = Field(description="React component name (e.g. Dashboard)")
    color_palette: str = Field(description="Primary visual tone: e.g. dark slate / emerald accents")
    react_code: str = Field(description="Complete, working React + Tailwind component code")


class UiDesignerAgent:
    """
    UI/UX Designer Agent in the Nexus Core IT Pack.
    Translates proposals into working frontend React components using the @nexus/ui design system.
    """

    def __init__(self, provider: BaseModelProvider) -> None:
        self.provider = provider

    def design_ui(self, proposal: ProductProposal, solution: SolutionBlueprint | None = None) -> UiSpecification:
        """Generate working React component code for the application's primary view."""
        prompt = f"""You are a Lead UI/UX Product Designer.
Design the primary interface for:
App: {proposal.title}
Concept: {proposal.ui_concept}
Features: {', '.join(proposal.core_features)}

Requirements:
- Use React with Tailwind CSS and modern dark slate aesthetic.
- Include realistic sample data so it can be previewed immediately.
- Return full valid React component code.
"""
        system = "You are an elite frontend UI designer specializing in sleek React and Tailwind interfaces."
        return self.provider.structured(prompt, UiSpecification, system_instruction=system)
